/* ===== Buttons Css ===== */
.signin-one .rounded-buttons .primary-btn {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow-2);
}
.signin-one .rounded-buttons .active.primary-btn, .signin-one .rounded-buttons .primary-btn:hover, .signin-one .rounded-buttons .primary-btn:focus {
  background: var(--primary-dark);
  color: var(--white);
  box-shadow: var(--shadow-4);
}
.signin-one .rounded-buttons .deactive.primary-btn {
  background: var(--gray-4);
  color: var(--dark-3);
  pointer-events: none;
}

.signin-one .rounded-buttons .primary-btn-outline {
  border-color: var(--primary);
  color: var(--primary);
}
.signin-one .rounded-buttons .active.primary-btn-outline, .signin-one .rounded-buttons .primary-btn-outline:hover, .signin-one .rounded-buttons .primary-btn-outline:focus {
  background: var(--primary-dark);
  color: var(--white);
}
.signin-one .rounded-buttons .deactive.primary-btn-outline {
  color: var(--dark-3);
  border-color: var(--gray-4);
  pointer-events: none;
}

/*===========================
  SING IN SING UP css 
===========================*/
.signin-one {
  padding-top: 100px;
  padding-bottom: 100px;
  background-color: var(--light-2);
}
.signin-one .form-input {
  margin-top: 16px;
}
.signin-one .form-input .main-btn {
  width: 100%;
}
.signin-one .form-input .text {
  font-size: 16px;
  line-height: 24px;
  color: var(--dark-3);
}
.signin-one .form-input .text a {
  color: var(--primary);
}
.signin-one .signin-form {
  background-color: var(--white);
  padding: 40px;
  border: 1px solid var(--gray-4);
  border-radius: 8px;
}
.signin-one .rounded-buttons {
  margin-top: 20px;
}
.signin-one .rounded-buttons .primary-btn {
  width: 100%;
}
.signin-one .rounded-buttons .primary-btn-outline {
  width: 100%;
}
.signin-one .form-input .help-block {
  margin-top: 2px;
}
.signin-one .form-input .help-block .list-unstyled li {
  font-size: 12px;
  line-height: 16px;
  color: var(--error);
}
.signin-one .form-input label {
  font-size: 12px;
  line-height: 18px;
  color: var(--dark-3);
  margin-bottom: 8px;
  display: inline-block;
}
.signin-one .form-input .input-items {
  position: relative;
}
.signin-one .form-input .input-items input, .signin-one .form-input .input-items textarea {
  width: 100%;
  height: 44px;
  border: 2px solid;
  padding-left: 44px;
  padding-right: 12px;
  position: relative;
  font-size: 16px;
}
.signin-one .form-input .input-items textarea {
  padding-top: 8px;
  height: 130px;
  resize: none;
}
.signin-one .form-input .input-items i {
  position: absolute;
  top: 11px;
  left: 13px;
  font-size: 20px;
  z-index: 9;
}
.signin-one .form-input .input-items.default input, .signin-one .form-input .input-items.default textarea {
  border-color: var(--gray-4);
  color: var(--dark-3);
}
.signin-one .form-input .input-items.default input:focus, .signin-one .form-input .input-items.default textarea:focus {
  border-color: var(--primary);
}
.signin-one .form-input .input-items.default input::placeholder, .signin-one .form-input .input-items.default textarea::placeholder {
  color: var(--dark-3);
  opacity: 1;
}
.signin-one .form-input .input-items.default i {
  color: var(--dark-3);
}
.signin-one .form-input .input-items.error input, .signin-one .form-input .input-items.error textarea {
  border-color: var(--error);
  color: var(--error);
}
.signin-one .form-input .input-items.error input::placeholder, .signin-one .form-input .input-items.error textarea::placeholder {
  color: var(--error);
  opacity: 1;
}
.signin-one .form-input .input-items.error i {
  color: var(--error);
}
.signin-one .form-style-two .form-input .input-items input, .signin-one .form-style-two .form-input .input-items textarea {
  border-radius: 5px;
  padding-left: 12px;
  padding-right: 44px;
}
.signin-one .form-style-two .form-input .input-items i {
  left: auto;
  right: 13px;
}

.signin-content .signin-title {
  font-size: 24px;
  line-height: 30px;
  color: var(--black);
}
.signin-content .text {
  font-size: 16px;
  line-height: 24px;
  color: var(--dark-3);
  margin-top: 8px;
}

/*===== SIGN IN / SIGN UP STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.signin-signup-style-3 { background: var(--light-2); padding: 70px 0; }
.signin-signup-style-3 .auth-card { background: var(--white); border: 1px solid var(--gray-4); border-radius: 14px; padding: 36px 32px; box-shadow: var(--shadow-3); }
.signin-signup-style-3 h3 { color: var(--black); }
.signin-signup-style-3 p, .signin-signup-style-3 .form-label { color: var(--dark-2); }
.signin-signup-style-3 .form-control { padding: 11px 14px; border-radius: 8px; border: 1px solid var(--gray-4); }

